import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(__dirname, '..', 'data', 'books.json');

function ensureDataFile() {
  mkdirSync(dirname(DATA_FILE), { recursive: true });
  try {
    readFileSync(DATA_FILE, 'utf8');
  } catch {
    writeFileSync(DATA_FILE, '[]', 'utf8');
  }
}

export function loadBooks() {
  ensureDataFile();
  const raw = readFileSync(DATA_FILE, 'utf8');
  return JSON.parse(raw);
}

function saveBooks(books) {
  ensureDataFile();
  writeFileSync(DATA_FILE, JSON.stringify(books, null, 2) + '\n', 'utf8');
}

export function getBook(id) {
  return loadBooks().find((b) => b.id === id) ?? null;
}

export function addBook({ title, author, notes = '' }) {
  const books = loadBooks();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes.trim(),
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.unshift(book);
  saveBooks(books);
  return book;
}

export function markFinished(id) {
  const books = loadBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return null;

  books[index] = {
    ...books[index],
    status: 'finished',
    finishedAt: new Date().toISOString(),
  };
  saveBooks(books);
  return books[index];
}

