export function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Reading List</title>
  <link rel="stylesheet" href="/styles.css">
</head>
<body>
  <header class="site-header">
    <a href="/" class="site-title">Reading List</a>
  </header>
  <main class="container">
    ${body}
  </main>
</body>
</html>`;
}

export function bookCard(book) {
  const statusLabel = book.status === 'finished' ? 'Finished' : 'Reading';
  return `<li class="book-card">
    <a href="/books/${escapeHtml(book.id)}" class="book-link">
      <span class="book-title">${escapeHtml(book.title)}</span>
      <span class="book-author">${escapeHtml(book.author)}</span>
    </a>
    <span class="status-badge status-${book.status}">${statusLabel}</span>
  </li>`;
}

