import express from 'express';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { loadBooks, getBook, addBook, markFinished } from './lib/books.js';
import { layout, escapeHtml, bookCard } from './lib/html.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.urlencoded({ extended: true }));
app.use(express.static(join(__dirname, 'public')));

app.get('/', (_req, res) => {
  const books = loadBooks();
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  const readingList =
    reading.length > 0
      ? `<ul class="book-list">${reading.map(bookCard).join('')}</ul>`
      : '<p class="empty">Nothing on your shelf right now.</p>';

  const finishedList =
    finished.length > 0
      ? `<ul class="book-list">${finished.map(bookCard).join('')}</ul>`
      : '<p class="empty">No finished books yet.</p>';

  const body = `
    <h1>My books</h1>

    <section>
      <h2>Currently reading</h2>
      ${readingList}
    </section>

    <section>
      <h2>Finished</h2>
      ${finishedList}
    </section>

    <form class="add-form" method="post" action="/books">
      <h2>Add a book</h2>
      <label for="title">Title</label>
      <input type="text" id="title" name="title" required>

      <label for="author">Author</label>
      <input type="text" id="author" name="author" required>

      <label for="notes">Notes (optional)</label>
      <textarea id="notes" name="notes" placeholder="Thoughts, quotes, page numbers…"></textarea>

      <button type="submit">Add book</button>
    </form>
  `;

  res.type('html').send(layout('Home', body));
});

app.post('/books', (req, res) => {
  const { title, author, notes } = req.body;
  if (!title?.trim() || !author?.trim()) {
    return res.redirect('/');
  }
  addBook({ title, author, notes });
  res.redirect('/');
});

app.get('/books/:id', (req, res) => {
  const book = getBook(req.params.id);
  if (!book) {
    return res.status(404).type('html').send(
      layout('Not found', '<h1>Book not found</h1><p><a href="/">Back to your list</a></p>')
    );
  }

  const statusLabel = book.status === 'finished' ? 'Finished' : 'Reading';
  const notesHtml = book.notes
    ? `<p class="notes-content">${escapeHtml(book.notes)}</p>`
    : '<p class="notes-empty">No notes yet.</p>';

  const finishButton =
    book.status === 'reading'
      ? `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
           <button type="submit">Mark as finished</button>
         </form>`
      : '';

  const body = `
    <div class="detail-header">
      <h1 class="detail-title">${escapeHtml(book.title)}</h1>
      <p class="detail-author">${escapeHtml(book.author)}</p>
      <div class="detail-meta">
        <span class="status-badge status-${book.status}">${statusLabel}</span>
      </div>
    </div>

    <div class="notes-block">
      <h2>Notes</h2>
      ${notesHtml}
    </div>

    <div class="actions">
      ${finishButton}
      <a href="/" class="btn btn-secondary">Back to list</a>
    </div>

    <p class="share-hint">Share this book: copy the URL from your browser's address bar.</p>
  `;

  res.type('html').send(layout(book.title, body));
});

app.post('/books/:id/finish', (req, res) => {
  const book = markFinished(req.params.id);
  if (!book) {
    return res.status(404).type('html').send(
      layout('Not found', '<h1>Book not found</h1><p><a href="/">Back to your list</a></p>')
    );
  }
  res.redirect(`/books/${book.id}`);
});

app.listen(PORT, () => {
  console.log(`Reading list running at http://localhost:${PORT}`);
});

